/* ---------- Live answer ---------- */
.lva{display:flex;flex-direction:column;gap:14px}
.lva-q{display:flex;justify-content:flex-end}
.lva-a{display:flex;flex-direction:column;gap:14px;min-height:230px}
/* on a card the first answer keeps the room its sources and follow-ups fill, so nothing climbs when they arrive */
.stage-in>.lva .lva-a{min-height:324px}
.lva-turn{display:flex;flex-direction:column;gap:12px}
.lva-th{display:flex;align-items:center;gap:8px;font-size:13.5px;color:var(--muted)}
.lva-tb{display:inline-flex;gap:6px;align-self:flex-start;padding:2px 8px;margin-left:-8px;border-radius:999px;transition:color var(--t-fast),background var(--t-fast)}
.lva-tb:hover{color:var(--fg2);background:var(--chip)}
.lva-tb>.i{transition:transform .2s var(--ease)}
.lva-tb[aria-expanded="true"]>.i{transform:rotate(180deg)}
.lva-tlist{list-style:none;margin:0;padding:2px 0 2px 12px;border-left:1px solid var(--rail);display:flex;flex-direction:column;gap:4px;font-size:13px;color:var(--muted)}
.lva-p{margin:0;font-size:14px;line-height:1.65}
.lva-p .w{display:inline;animation:lvw .5s var(--ease) both}
@keyframes lvw{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.cite{display:inline-grid;place-items:center;min-width:17px;height:17px;padding:0 4px;margin:0 2px;border-radius:5px;background:var(--hover);font-size:10.5px;font-weight:500;color:var(--fg2);vertical-align:2px;cursor:default;transition:background .2s,color .2s}
.cite:hover,.cite.on{background:var(--accent-bg);color:var(--accent-fg,var(--accent))}
.lva-p .cite{animation:lvw .5s var(--ease) both}
.lva-src{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--muted)}
.lva-sb{display:inline-flex;align-items:center;gap:8px;height:28px;padding:0 9px 0 5px;border-radius:var(--r-pill);color:var(--fg2);transition:background .2s,color .2s}
.lva-sb:hover,.lva-sb[aria-expanded="true"]{background:var(--chip);color:var(--fg)}
.lva-sb>.i{color:var(--muted);transition:transform .35s var(--ease)}
