/* ---------- Task table ---------- */
.ttx{overflow:hidden;position:relative}
/* the header holds the table's name and a summary, or, while rows are picked, what you can do to them */
.ttx-hd{position:relative;height:50px;border-bottom:1px solid var(--line)}
.ttx-ti,.ttx-sb{position:absolute;inset:0;display:flex;align-items:center;transition:opacity .28s var(--ease),transform .45s var(--ease),filter .28s var(--ease)}
.ttx-ti{gap:10px;padding:0 16px}
.ttx-ti b{font-size:13.5px;font-weight:500}
.ttx-sum{font-size:12.5px}
.ttx-sb{gap:2px;padding:0 10px 0 16px;opacity:0;transform:translateY(10px);filter:blur(3px);pointer-events:none}
.ttx.selecting .ttx-ti{opacity:0;transform:translateY(-10px);filter:blur(3px);pointer-events:none}
.ttx.selecting .ttx-sb{opacity:1;transform:none;filter:none;pointer-events:auto}
.ttx-n{margin-right:8px;font-size:13px;font-weight:500;white-space:nowrap}
.ttx-sp{flex:1}
.ttx-sb .pill.ttx-del{color:var(--bad)}
.ttx-sb .pill.ttx-del:hover{background:color-mix(in srgb,var(--bad) 10%,transparent);color:var(--bad)}
.ttx-sc{overflow-x:auto}
.ttx-t{width:100%;border-collapse:collapse;font-size:13px;min-width:560px}
.ttx-t th{height:36px;padding:0 8px;text-align:left;font-weight:500;font-size:12px;color:var(--muted);border-bottom:1px solid var(--line);white-space:nowrap}
.ttx-t th.ck,.ttx-t td.ck{width:36px;padding-left:16px}
.ttx-t th.r,.ttx-t td.r{text-align:right}
.ttx-t th:last-child,.ttx-t td:last-child{padding-right:16px}
/* a header sorts its column: a quiet arrow shows on hover and stays on the column the rows are sorted by */
.ttx-s{display:inline-flex;align-items:center;gap:3px;height:24px;margin:0 -6px;padding:0 6px;border-radius:6px;color:inherit;font:inherit;transition:color .2s,background-color .2s}
.ttx-s:hover{color:var(--fg);background:var(--row)}
.ttx-s .ar{display:grid;opacity:0;transition:opacity .2s,transform .35s var(--ease)}
.ttx-s:hover .ar{opacity:.45}
.ttx-s.on{color:var(--fg)}
.ttx-s.on .ar{opacity:1}
.ttx-s.on.desc .ar{transform:rotate(180deg)}
.ttx-t td{height:46px;padding:0 8px;border-bottom:1px solid var(--line);white-space:nowrap}
.ttx-t tbody tr:last-child td{border-bottom:0}
/* rows: the shared hover, and a slightly deeper grey while picked */
.ttx-t tbody tr[data-id]{cursor:pointer;transition:background-color .25s var(--ease)}
.ttx-t tbody tr[data-id]:hover{background:var(--row)}
.ttx-t tbody tr.sel{background:color-mix(in srgb,var(--fg) 6%,transparent)}
.ttx-t tbody tr.sel:hover{background:color-mix(in srgb,var(--fg) 8%,transparent)}
.ttx-t .nm{font-weight:500}
.ttx-t .ag{display:flex;align-items:center;gap:7px;color:var(--fg2)}
.ttx-t .ag .av{width:20px;height:20px;font-size:9.5px}
.ttx-t td.num{color:var(--fg2)}
.ttx-t td.up{color:var(--muted)}
/* checkboxes: the tick springs in; select-all shows a dash while only some rows are picked */
.ttx-cb{display:grid;place-items:center;width:16px;height:16px;border-radius:5px;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--muted) 80%,var(--surface));color:var(--on-accent,#fff);transition:background-color .2s,box-shadow .2s}
.ttx-cb:hover{box-shadow:inset 0 0 0 1.5px var(--muted)}
.ttx-cb[aria-checked="true"],.ttx-cb[aria-checked="mixed"]{background:var(--accent);box-shadow:inset 0 0 0 1px var(--accent-mark,var(--accent))}
.ttx-cb svg{grid-area:1/1;width:11px;height:11px;opacity:0;transform:scale(.4);transition:opacity .15s,transform .3s cubic-bezier(.34,1.4,.64,1)}
.ttx-cb[aria-checked="true"] .ck-y,.ttx-cb[aria-checked="mixed"] .ck-m{opacity:1;transform:none}
/* status: a soft pill in the status colour; Running, Done and Failed have their own, Queued and Paused stay grey */
.ttx-st{--sc:var(--muted);display:inline-flex;align-items:center;height:22px;padding:0 9px 0 7px;border-radius:var(--r-pill);font-size:12px;font-weight:500;color:var(--sc);background:color-mix(in srgb,var(--sc) 11%,transparent);transition:color .35s var(--ease),background-color .35s var(--ease)}
.ttx-st .sv{display:inline-flex;align-items:center;gap:6px}
/* running reads in the accent's text colour on a tint of its mark, so a light accent like lime stays legible */
.ttx-st[data-s="run"]{--sc:var(--accent-fg,var(--accent));background:color-mix(in srgb,var(--accent-mark,var(--accent)) 11%,transparent)}
.ttx-st[data-s="done"]{--sc:var(--ok)}
.ttx-st[data-s="fail"]{--sc:var(--bad)}
.ttx-st .spin{width:10px;height:10px}
/* a new status fades in out of a blur; a cancelled row slides away before it goes */
.ttx-sin{animation:ttxsin .32s var(--ease)}
@keyframes ttxsin{from{opacity:0;filter:blur(3px)}}
.ttx-t tbody tr.ttx-out{opacity:0;transform:translateX(14px);transition:opacity .24s var(--ease),transform .24s var(--ease)}
.ttx-st .i{width:12px;height:12px}
/* when every task is gone */
.ttx-t tbody tr.ttx-empty td{height:auto;padding:36px 16px 34px;text-align:center;white-space:normal}
.ttx-em{display:flex;flex-direction:column;align-items:center;gap:3px}
.ttx-em .ic{display:grid;place-items:center;width:36px;height:36px;margin-bottom:8px;border-radius:12px;background:var(--chip);color:var(--muted)}
.ttx-em b{font-size:13.5px;font-weight:500}
.ttx-em span{font-size:12.5px;color:var(--muted)}
.ttx-em .pill{margin-top:10px}
/* narrower: Updated goes, long names end in an ellipsis; on a phone Cost goes too and the agent is just its avatar */
@container (max-width:560px){.ttx-t{min-width:0}.ttx-t th:nth-child(6),.ttx-t td:nth-child(6){display:none}.ttx-t th:nth-child(5),.ttx-t td:nth-child(5){padding-right:16px}.ttx-t td.nm{width:100%;max-width:0;overflow:hidden;text-overflow:ellipsis}}
@container (max-width:420px){.ttx-t th:nth-child(5),.ttx-t td:nth-child(5){display:none}.ttx-t th:nth-child(4),.ttx-t td:nth-child(4){padding-right:16px}.ttx-t .ag{font-size:0;gap:0}.ttx-sb{padding-right:6px}.ttx-sb .pill{padding:0 9px}.ttx-sb .pill .i{display:none}}
@container (max-width:340px){.ttx-ti{padding:0 12px}.ttx-sb{gap:0;padding:0 4px 0 12px}.ttx-n{margin-right:4px}.ttx-sb .pill{padding:0 7px}.ttx-t th.ck,.ttx-t td.ck{padding-left:12px}.ttx-t th:nth-child(4),.ttx-t td:nth-child(4){padding-right:12px}}

