DM.def('status-pill', (r, c) => {
  const pill = $('.spl-pill', r), box = $('.spl-in', r), root = $('.spl', r);
  pill.insertAdjacentHTML('beforeend', '<div class="spl-track"><div class="spl-fill"></div></div>');
  const fill = $('.spl-fill', r);
  // the switch morphs in three beats, so the words and the shape never move at once: the line fades out with its track,
  // the pill changes shape while it's empty, then the new layout fades in with the track under it
  let morph = 0;
  seg($('.seg2', r), v => {
    const bar = v === 'bar', id = ++morph; if (root.classList.contains('bar') === bar) return;
    pill.style.width = pill.offsetWidth + 'px'; box.classList.add('out'); root.classList.add('mo');
    c.later(REDUCE ? 0 : 170, () => { if (id !== morph) return; root.classList.toggle('bar', bar); fit(); });
    c.later(REDUCE ? 0 : 430, () => { if (id !== morph) return; morph = 0; box.classList.remove('out'); root.classList.remove('mo'); });
  });
  /* both variants hug their content; the bar keeps a little extra room for its track */
  function fit(){
    box.style.width = 'max-content'; const w = box.scrollWidth; box.style.width = '';
    pill.style.width = (root.classList.contains('bar') ? Math.max(w + 24, 300) : w) + 'px';
  }
  function set(htmlStr, pct){
    pill.style.width = pill.offsetWidth + 'px';
    box.classList.add('out');
    // mid-switch, the morph brings the line back once the shape has settled
    c.later(180, () => { box.innerHTML = htmlStr; if (!morph) box.classList.remove('out'); fit(); });
    if (pct !== undefined) fill.style.width = pct + '%';
  }
  const think = '<span class="think on"><i></i><i></i><i></i><i></i></span>';
  box.innerHTML = '<span class="g"><span class="dot" style="color:var(--faint)"></span></span><span class="fg2">Ready for a task</span><span class="end"></span>';
  requestAnimationFrame(fit);
  const idle = '<span class="g"><span class="dot" style="color:var(--faint)"></span></span><span class="fg2">Ready for a task</span><span class="end"></span>';
  c.run(async () => { for (;;){
    await c.wait(1100);
    set(`<span class="g" style="color:var(--fg)">${think}</span><span class="shim">Thinking</span><span class="end"></span>`, 8); await c.wait(1800);
    set(`<span class="g" style="color:var(--fg)"><span class="radar"></span></span><span class="shim">Reading Figma frames</span><span class="m n">1 of 4</span><span class="end"></span>`, 22);
    await c.wait(400);
    // the count ticks over in place, under a steady line
    for (let i = 2; i <= 4; i++){ await c.wait(650); const n = $('.n', box); if (n) n.textContent = i + ' of 4'; fill.style.width = (22 + i * 8) + '%'; }
    await c.wait(700);
    set(`<span class="g" style="color:var(--fg)"><span class="spin"></span></span><span class="shim">Editing</span><span class="fchip" style="height:24px"><span class="ft re">TSX</span>PricingCard.tsx</span><span class="end"></span>`, 64); await c.wait(2000);
    set(`<span class="g" style="color:var(--warn)"><span class="dot"></span></span><span>Waiting for your approval</span><button class="pill ink sm">Review</button>`, 72);
    /* waits for Review, and carries on by itself after a while so the loop never stalls */
    await new Promise(res => { c.later(220, () => { const b = $('.pill', box); if (b) b.onclick = res; }); c.later(8000, res); });
    set(`<span class="g" style="color:var(--fg)"><span class="spin"></span></span><span class="shim">Applying 4 changes</span><span class="end"></span>`, 88); await c.wait(1600);
    set(`<span class="g" style="color:var(--ok)">${I('ok')}</span><span>Done</span><span class="m">4 files changed · 18s</span><span class="end"></span>`, 100);
    await c.wait(3200); set(idle, 0);
  } });
});

c23.css:
/* ---------- Context meter ---------- */
/* a pill with the ring opens what fills the context: one bar split by kind, a legend whose rows list their items, and Compact */
/* it never anchors the page's scroll, so the page can't follow it as it changes; on a card it sits in the middle of its room */
.ctm{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:8px;width:100%;max-width:340px;margin-inline:auto;overflow-anchor:none}
.stage-in:has(>.ctm){overflow-anchor:none}
.stage-in>.ctm{min-height:inherit}
.ctm-tg{display:inline-flex;align-items:center;gap:8px;height:32px;padding:0 10px 0 7px;border-radius:var(--r-pill);font-size:13px;color:var(--fg2);background:var(--surface);box-shadow:var(--shadow);transition:box-shadow var(--t-fast)}
.ctm-tg:hover{box-shadow:var(--shadow-pop)}
.ctm-tg .ctm-pc{color:var(--fg);font-weight:500}
.ctm-tg>svg:last-child{color:var(--muted);transition:transform .32s var(--ease)}
.ctm[data-open="0"] .ctm-tg>svg:last-child{transform:rotate(-90deg)}
/* the panel keeps its room when shut, so nothing below it moves, and nothing clips its shadow */
.ctm-pop{width:100%;padding:14px 16px 12px;display:flex;flex-direction:column;gap:12px;transition:opacity .32s var(--ease),transform .42s var(--ease),visibility 0s}
.ctm[data-open="0"] .ctm-pop{opacity:0;transform:translateY(-6px);visibility:hidden;pointer-events:none;transition:opacity .16s var(--ease),transform .32s var(--ease),visibility 0s .32s}
.ctm-ph{display:flex;align-items:baseline;justify-content:space-between;gap:12px;font-size:13px;color:var(--muted)}
.ctm-ph b{color:var(--fg);font-weight:500}
.ctm-bar{display:flex;gap:2px;height:8px;border-radius:4px;background:var(--chip);overflow:hidden}
.ctm-bar i{height:100%;width:0;flex:none;background:var(--c);transition:width .42s var(--ease),opacity .16s}
.ctm-bar.hl i:not(.on){opacity:.25}
.ctm-leg{display:flex;flex-direction:column;margin:0 -6px}
.ctm-l{display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:8px;font-size:13px;color:var(--fg2);cursor:default;transition:background var(--t-fast)}
.ctm-l:hover{background:var(--row)}
.ctm-l .sw{width:8px;height:8px;border-radius:2px;flex:none;background:var(--c)}
.ctm-l .v{margin-left:auto;color:var(--fg)}
/* the message line keeps its room while empty, so a warning or a result fades in without moving anything */
.ctm-msg{min-height:18px;font-size:13px;line-height:18px}
.ctm-msg>span{display:flex;align-items:flex-start;gap:6px;opacity:0;transition:opacity .32s var(--ease)}
.ctm-msg.on>span{opacity:1}
.ctm-msg>span>svg{flex:none;margin-top:2px}
.ctm-msg.warn{color:var(--warn)}
.ctm-msg.ok{color:var(--ok)}
.ctm-f{display:flex;align-items:center;gap:10px;padding-top:10px;border-top:1px solid var(--line)}
.ctm-f .ctm-hint{flex:1;min-width:0;font-size:13px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the ring: inside the meter's pill, and as its own button where Agent harness puts it in the composer */
.ctm-ft{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--fg2)}
.ctm-ring{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;flex:none;transition:background var(--t-fast)}
.ctm-ring:hover{background:var(--chip)}
.ctm-tg .ctm-ring{width:20px;height:20px;background:none}
.ctm-ring svg{width:18px;height:18px;transform:rotate(-90deg);overflow:visible}
.ctm-ring circle{fill:none;stroke-width:2.6}
.ctm-ring .tr{stroke:var(--rail)}
.ctm-ring .fl{stroke:var(--accent-mark,var(--accent));stroke-linecap:round;stroke-dasharray:0 100;transition:stroke-dasharray .42s var(--ease),stroke .32s}
.ctm.hot .ctm-ring .fl{stroke:var(--warn)}

