DM.def('voice-capture', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{pause}', I('pause'));
  const box = $('.vcx', r), tx = $('.vcx-tx', r), cv = $('.vcx-wave', r), st = $('.vcx-st', r), pop = $('.vcx-fix', r);
  const words = 'Move the yearly toggle above the cards and make the save badge say 20% off for annual plans'.split(' ');
  const low = { 3:['toggle','toddle','tunnel'], 10:['save','sale','saving'] };
  let samples = [], speak = 0, last = 0, paused = false, secs = 0, done = false;
  c.every(1000, () => { if (!paused && !done){ secs++; $('.vcx-t', r).textContent = Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0'); } });
  c.loop(t => {
    if (done) return false;
    if (t - last > 50){ last = t; samples.push(!paused && speak > 0 ? .2 + Math.random() * .8 : 0); if (samples.length > 300) samples.shift(); if (speak > 0) speak--; }
    const dpr = devicePixelRatio || 1, w = cv.clientWidth, h = cv.clientHeight; if (!w) return;
    if (cv.width !== w * dpr){ cv.width = w * dpr; cv.height = h * dpr; }
    const x = cv.getContext('2d'); x.setTransform(dpr, 0, 0, dpr, 0, 0); x.clearRect(0, 0, w, h);
    const cs = getComputedStyle(r); const n = Math.floor(w / 5);
    for (let i = 0; i < n; i++){ const v = samples[samples.length - n + i] || 0, px = i * 5 + 2; x.globalAlpha = Math.min(1, i / 14, (n - i) / 3 + .2);
      x.fillStyle = v ? cs.getPropertyValue('--fg2').trim() : cs.getPropertyValue('--faint').trim();
      const bh = v ? Math.max(4, v * (h - 6)) : 2; x.beginPath(); x.roundRect ? x.roundRect(px, h / 2 - bh / 2, 2.5, bh, 1.2) : x.rect(px, h / 2 - bh / 2, 2.5, bh); x.fill(); }
  });
  const pb = $('.vcx-pause', r);
  pb.onclick = () => { paused = !paused; box.classList.toggle('paused', paused); pb.innerHTML = I(paused ? 'mic' : 'pause'); pb.dataset.tip = paused ? 'Resume' : 'Pause'; swap(st, paused ? 'Paused' : 'Listening'); };
  function finish(){
    done = true; box.classList.add('done'); swap(st, 'Check what I heard'); pb.remove();
    $$('.low', tx).forEach(l => { l.dataset.tip = 'Not sure about this word'; });
  }
  const settle = t => { $('.vcx-acts', r).innerHTML = `<span class="muted" style="font-size:12.5px">${t}</span><span class="sp"></span><button class="pill ghost sm vcx-again">${I('refresh','xs')}Record again</button>`; $('.vcx-again', r).onclick = () => DM.mount(r.closest('.card')); };
  $('.vcx-done', r).onclick = () => { if (!done) finish(); else { swap(st, 'Sent'); settle('Sent to the agent'); } };
  $('.vcx-x', r).onclick = () => { done = true; tx.innerHTML = ''; pb.remove(); box.classList.add('done'); swap(st, 'Cancelled'); settle('Nothing was sent'); };
  c.on(tx, 'click', e => {
    const l = e.target.closest('.low'); if (!l) return;
    const alts = low[l.dataset.i];
    pop.innerHTML = '<div class="ph">Did you mean</div>' + alts.map(a => `<button class="mi" data-close data-w="${a}">${a}</button>`).join('');
    hideTip(); const hr = box.getBoundingClientRect(), lr = l.getBoundingClientRect();
    pop.style.left = (lr.left - hr.left) + 'px'; pop.style.top = (lr.bottom - hr.top + 6) + 'px'; pop.classList.add('open');
    $$('.mi', pop).forEach(b => b.onclick = ev => { ev.stopPropagation(); l.textContent = b.dataset.w; l.classList.add('fixed'); l.dataset.tip = 'Fixed'; pop.classList.remove('open'); });
    e.stopPropagation();
  });
  c.on(document, 'click', e => { if (!pop.contains(e.target)) pop.classList.remove('open'); });
  c.run(async () => {
    await c.wait(700);
    for (let i = 0; i < words.length; i++){
      while (paused){ await c.wait(100); }
      if (done) return;
      speak = 5; tx.insertAdjacentHTML('beforeend', low[i] ? `<span class="w"><span class="low" data-i="${i}">${words[i]}</span> </span>` : `<span class="w">${words[i]} </span>`);
      await c.wait(170 + Math.random() * 150);
    }
    await c.wait(900); if (!done) finish();
  });
});

c26.css:
/* ---------- Agent lanes ---------- */
.aln{padding:8px}
.aln-h{display:flex;align-items:center;gap:10px;padding:8px 10px 10px}
.aln-ic{color:var(--fg2);display:grid}
.aln-t{font-weight:500}
.aln-m{font-size:12.5px;margin-right:auto}
.aln-lane{border-radius:14px;transition:background .25s}
.aln-lane:hover{background:var(--row)}
.aln-row{display:grid;grid-template-columns:34px minmax(0,1.2fr) minmax(0,1fr) auto;align-items:center;gap:12px;width:100%;padding:10px;text-align:left}
.aln-av{width:34px;height:34px;border-radius:11px;display:grid;place-items:center}
.aln-n{font-weight:500;font-size:13.5px}
.aln-a{display:block;font-size:12.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aln-a.live{color:var(--fg2)}
.aln-tr{display:flex;gap:3px}
.aln-tr i{flex:1;height:4px;border-radius:2px;background:var(--line);position:relative;overflow:hidden}
.aln-tr i::after{content:"";position:absolute;inset:0;border-radius:2px;background:var(--c,var(--accent));transform:scaleX(0);transform-origin:left;transition:transform .9s var(--ease)}
.aln-tr i.on::after{transform:scaleX(1)}
.aln-tr i.run::after{transform:scaleX(.5);transition-duration:2s}
.aln-st{min-width:92px;display:flex;justify-content:flex-end}
.aln-det{padding:0 10px 10px 56px;font-size:12.5px;color:var(--fg2)}
.aln-det div{display:flex;gap:8px;padding:3px 0}
.aln-det .muted{margin-left:auto}
/* a hand-off opens a row between the lanes and closes it again, so the lanes glide instead of jumping */
.aln-hf{transition-duration:var(--t-slow)}
.aln-hand{display:flex;align-items:center;gap:8px;margin:2px 10px;padding:7px 12px;border-radius:10px;background:color-mix(in srgb,var(--pl-bg) 55%,transparent);color:var(--pl);font-size:12.5px}
@media (max-width:600px){.aln-row{grid-template-columns:34px minmax(0,1fr) auto}.aln-tr{display:none}}

