/* on a narrow stage the duration gets its own row, and the two buttons stay together under it on the right */
@container (max-width:340px){.pgx-f{flex-wrap:wrap}.pgx-f .sp{flex-basis:100%}.pgx-no{margin:8px 0 0 auto}.pgx-ok{margin-top:8px}}
/* how long: a small dropdown, the way a menu of choices usually looks */
.pgx-db{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 8px 0 10px;margin-left:-2px;border-radius:var(--r-pill);font-size:13px;color:var(--fg2);white-space:nowrap;transition:background .16s,color .16s}
