_shared.css:
/* Designme shared core: tokens for Blueprint (default) and Soft (<html data-style="soft">), light and dark (<html data-theme="dark">) */
:where([data-c]) [hidden]{display:none!important}
/* hold(): an end state centred in the height its component had */
.held{display:flex;flex-direction:column;justify-content:center}
/* Soft 2: one quiet surface per object, grey type for finished work, motion only on what is happening now */
:root{
  --motion:soft;
  --page:#f7f7f7; --stage:#f9f9f9; --surface:#ffffff; --raised:#ffffff;
  --fg:#171717; --fg2:#525252; --muted:#6a6a6a; --faint:#c4c4c4; --rail:#d4d4d4; --line:#e8e8e8;
  --chip:#f3f3f3; --hover:#ebebeb; --press:#e3e3e3; --wash:#f9f9f9; --row:color-mix(in srgb,var(--fg) 4%,transparent);
  --soft:#ececec; --soft-h:#e3e3e3; --soft-ring:inset 0 0 0 1px rgba(0,0,0,.06); --dis:#a6a6a6;
  --shadow-lift:0 0 0 1px rgba(0,0,0,.1),0 2px 4px rgba(0,0,0,.04),0 16px 32px -10px rgba(0,0,0,.16);
  /* the accent has three roles: --accent fills (with --on-accent on top, 4.5:1), --accent-fg is text and icons in the accent
     (4.5:1 on the surface, and on the chips and tints it sits on) and --accent-mark is lines, rings and chart marks (3:1). A
     light accent like lime keeps its fills and gets a darker mark and ink-coloured text on a light page */
  --accent:#116ff8; --accent-2:#0b5ed7; --accent-bg:#eaf2ff; --on-accent:#ffffff; --accent-fg:#0f5fd5; --accent-mark:#116ff8; --sel:color-mix(in srgb,var(--accent) 6%,transparent);
  --ink:#1b1b1f; --on-ink:#ffffff;
  --ok:#147c3b; --ok-bg:#e8f6ee; --warn:#b25209; --warn-bg:#fdf3df; --bad:#c13535; --bad-bg:#fdecec;
  --merge:#8250df; --merge-bg:#f2ecfd; --add:#187633; --del:#c7212c;
  --pb:#1460d0; --pb-bg:#eaf2ff; --pl:#6b47d6; --pl-bg:#f2edff; --pm:#10754a; --pm-bg:#e7f8f0; --pp:#ad560d; --pp-bg:#fff2e6;
  --pr:#c93451; --pr-bg:#ffeef1; --py:#8b6804; --py-bg:#fffae3; --pk:#c1307a; --pk-bg:#fff0f7; --pt:#0e757e; --pt-bg:#e6f9fa;
  --ts:#3178c6; --react:#0a7891;
  /* every raised surface carries its own hairline edge, so nothing needs a separate ring */
  --shadow:0 0 0 1px rgba(0,0,0,.07),0 1px 2px rgba(0,0,0,.04),0 8px 16px -8px rgba(0,0,0,.08);
  --shadow-pop:0 0 0 1px rgba(0,0,0,.08),0 1px 1px rgba(0,0,0,.02),0 4px 8px -4px rgba(0,0,0,.04),0 16px 24px -8px rgba(0,0,0,.06);
  --shadow-toast:0 0 0 1px rgba(0,0,0,.06),0 4px 12px rgba(0,0,0,.08);
  --hl:#fdeb9a; --hl-ok:#d3f1df;
  --r-card:16px; --r-in:12px; --r-sm:8px; --r-pill:999px;
  --sans:"Inter",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
  --mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
  --ease:cubic-bezier(.22,1,.36,1); --ease-io:cubic-bezier(.65,0,.35,1);
  --t-fast:.22s; --t:.45s; --t-slow:.7s;
}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){
  --page:#111111; --stage:#1c1c1c; --surface:#262626; --raised:#2c2c2c;
  --fg:#f2f2f2; --fg2:#ababab; --muted:#9a9a9a; --faint:#555555; --rail:#414141; --line:#333333;
  --chip:#303030; --hover:#373737; --press:#3f3f3f; --wash:#2c2c2c; --row:color-mix(in srgb,var(--fg) 5.5%,transparent);
  --soft:#323232; --soft-h:#3a3a3a; --soft-ring:inset 0 0 0 1px rgba(255,255,255,.07); --dis:#5f5f5f;
  --shadow-lift:0 0 0 1px rgba(255,255,255,.16),0 2px 4px rgba(0,0,0,.3),0 16px 32px -10px rgba(0,0,0,.6);
  --accent:#3d8bff; --accent-2:#5b9bff; --accent-bg:rgba(61,139,255,.12); --on-accent:#121212; --accent-fg:#6fa8ff; --accent-mark:#3d8bff; --sel:color-mix(in srgb,var(--accent) 9%,transparent);
  --ink:#f2f2f2; --on-ink:#161616;
