.pop .sep{height:1px;background:var(--line);margin:4px 2px}
/* every list row hovers with --row; an icon chip or track inside a hovered row lifts above it (white in light mode, one step lighter in dark) */
:root[data-theme="dark"] :is(.alg-it:hover .alg-ic,.plx-s:hover .n,.tpx-r:hover .tr){background:var(--hover)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) :is(.alg-it:hover .alg-ic,.plx-s:hover .n,.tpx-r:hover .tr){background:var(--hover)}}

