/* bare: components that live in the chat stream sit on the chat surface, no card */
.card.bare .stage-in .panel:not(.keep){background:none;box-shadow:none;padding-left:0;padding-right:0;border-radius:0}
/* chart palette, saturated */
:root{--c1:var(--accent-mark,var(--accent));--c2:#7c4dff;--c3:#00b37e;--c4:#ff8a00;--c5:#ff4d6d;--c6:#00b8d9}
/* the accent as a ramp, for charts whose parts are shares of one thing: full strength, then lighter steps toward the surface */
:root{--a1:var(--c1);--a2:color-mix(in oklab,var(--c1) 72%,var(--surface));--a3:color-mix(in oklab,var(--c1) 50%,var(--surface));--a4:color-mix(in oklab,var(--c1) 32%,var(--surface))}
