    b.innerHTML = I('check','xs') + 'Drafted'; swap(ms, 'Review what the agent drafted');
  });
  let touched = false; c.on(form, 'pointerdown', () => { touched = true; }); c.on(form, 'keydown', () => { touched = true; });
