DM.def('comments', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{check}', I('check','xs')).replace('{up}', I('up','xs'));
  const th = $('.cmx-th', r), inp = $('.cmx-box input', r), go = $('.cmx-go', r), men = $('.cmx-men', r), root = $('.cmx', r);
  const P = { MK:['Maya Kim','var(--pl)'], JO:['Jon Ortiz','var(--pm)'], DA:['Design agent','var(--pb)'] };
  const fmt = t => t.replace(/@(agent|maya|jon)/gi, m => `<span class="m">${m}</span>`);
  function add(who, t, when, ag){ const el = html(`<div class="cmx-c${ag ? ' ag' : ''}">${AV(who, P[who][1])}<div class="b"><span class="n"><b>${P[who][0]}</b><span>${when}</span></span><span class="tx">${ag ? '' : fmt(t)}</span></div></div>`); th.appendChild(el); enter(el); return el; }
  add('MK', 'The secondary button feels too faint next to the CTA.', '2h');
  add('JO', 'Agree. Can we keep it outlined though?', '1h');
  async function agent(q){
    const el = add('DA', '', 'now', true), tx = $('.tx', el); tx.innerHTML = '<span class="think on" style="color:var(--accent-mark,var(--accent))"><i></i><i></i><i></i><i></i></span>'; await c.wait(900); tx.innerHTML = '';
    const a = /outline|border/i.test(q + ' outlined') ? 'Kept it outlined and raised the text to #5B6472, which passes AA at 5.9 : 1. Want me to apply it to the other 2 frames?' : 'On it. I will post the change here when it is ready.';
    for (const w of a.split(' ')){ tx.insertAdjacentHTML('beforeend', `<span class="w">${w} </span>`); await c.wait(40); }
    const act = html(`<div class="act"><button class="pill accent sm">Apply to all</button><button class="pill ghost sm">Just this one</button></div>`); $('.b', el).appendChild(act); enter(act);
    $$('button', act).forEach((b, i) => b.onclick = () => { act.innerHTML = `<span class="cmx-rv">${I('ok','xs')}${i ? 'Applied to frame 2' : 'Applied to 3 frames'}</span>`; enter(act.firstChild); });
  }
  function send(){ const v = inp.value.trim(); if (!v) return; add('MK', v, 'now'); inp.value = ''; go.disabled = true; men.classList.remove('open'); if (/@agent/i.test(v)) c.run(() => agent(v)); }
  const opts = [['DA','agent','Design agent'],['MK','maya','Maya Kim'],['JO','jon','Jon Ortiz']];
  inp.oninput = () => { go.disabled = !inp.value.trim(); const m = inp.value.match(/@(\w*)$/);
    if (m){ const list = opts.filter(o => o[1].startsWith(m[1].toLowerCase())); men.innerHTML = list.map(o => `<button class="mi" data-h="${o[1]}">${AV(o[0], P[o[0]][1]).replace('class="av" style="', 'class="av" style="width:20px;height:20px;font-size:9px;')}<span>${o[2]}<span class="d">@${o[1]}</span></span></button>`).join(''); men.classList.toggle('open', list.length > 0);
      $$('.mi', men).forEach(b => b.onmousedown = e => { e.preventDefault(); inp.value = inp.value.replace(/@\w*$/, '@' + b.dataset.h + ' '); men.classList.remove('open'); go.disabled = false; inp.focus({ preventScroll:true }); }); }
    else men.classList.remove('open'); };
  inp.onkeydown = e => { if (e.key === 'Enter'){ const f = $('.mi', men); if (men.classList.contains('open') && f){ f.onmousedown(e); } else send(); } if (e.key === 'Escape') men.classList.remove('open'); };
  go.onclick = send;
  const rs = $('.cmx-res', r);
  rs.onclick = () => { const d = root.classList.toggle('done'); rs.innerHTML = d ? I('undo','xs') + 'Reopen' : I('check','xs') + 'Resolve'; $('.cmx-pin', r).style.background = d ? 'var(--ok)' : ''; };
  c.later(1000, () => c.run(async () => { for (const ch of '@agent can you keep it outlined but darker?'){ inp.value += ch; inp.oninput(); await c.wait(28); } men.classList.remove('open'); await c.wait(300); send(); }));
});

