.tk-list{list-style:none;margin:0;padding:6px 0 0;display:flex;flex-direction:column}
.tk-st{display:flex;gap:10px;padding:6px 0}
.tk-st .mk{width:18px;height:18px;flex:none;margin-top:1px;display:grid;place-items:center;border-radius:50%;color:var(--muted);transition:background .32s,color .32s}
