.tk-st.done .mk{background:var(--ok-bg);color:var(--ok)}
.tk-st.retry .mk{background:var(--warn-bg);color:var(--warn)}
.tk-st .tx{flex:1;min-width:0;display:flex;flex-direction:column}
.tk-st .lab{color:var(--fg);transition:color .32s}
