DM.def('memory-panel', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{book}', I('book'));
  let M = [
    ['brand','Primary buttons use the accent blue, never black','From the Pricing review, Sep 12'],
    ['brand','Headlines stay under eight words','You told the agent, Aug 30'],
    ['process','Ask Maya before publishing to the shared library','From a Slack thread, Sep 4'],
    ['brand','Card radius is 16px on web, 12px in the app','From tokens.css'],
    ['process','Run the launch checklist before every PR','You told the agent, Sep 20'],
    ['process','Weekly QA posts go to #design, not #general','From settings'],
    ['brand','No em dashes in product copy','You told the agent, Oct 2']
  ].map((m, i) => ({ id:i, k:m[0], t:m[1], s:m[2] }));
  const list = $('.mmx-list', r), st = $('.mmx-st', r); let f = 'all', nid = 100;
  const col = k => k === 'brand' ? 'var(--pb)' : 'var(--pt)';
  const count = () => swap(st, M.length + (M.length === 1 ? ' memory' : ' memories'));
  function item(m){
    const el = html(`<div class="mmx-m" data-id="${m.id}"><span class="dot" style="color:${col(m.k)}"></span><span class="t" spellcheck="false">${m.t}<span class="src" contenteditable="false">${m.s}</span></span><span class="acts"><button class="ib ed" aria-label="Edit" data-tip="Edit">${I('edit','xs')}</button><button class="ib rm" aria-label="Forget" data-tip="Forget">${I('trash','xs')}</button></span></div>`);
    const t = $('.t', el); if (m.isNew) el.classList.add('new');
    $('.ed', el).onclick = () => { const src = $('.src', t); src.remove(); t.contentEditable = 'true'; t.focus({ preventScroll:true }); const s = document.getSelection(); s.selectAllChildren(t); s.collapseToEnd();
      const done = () => { t.contentEditable = 'false'; m.t = t.textContent.trim() || m.t; m.s = 'Edited by you, just now'; t.textContent = m.t; t.appendChild(src); src.textContent = m.s; };
      t.onkeydown = e => { if (e.key === 'Enter'){ e.preventDefault(); t.blur(); } }; t.onblur = done; };
    $('.rm', el).onclick = () => { const i = M.indexOf(m); M.splice(i, 1); count();
      const g = html(`<div class="mmx-gone"><span>Forgot “${m.t.slice(0, 32)}${m.t.length > 32 ? '…' : ''}”</span><button>Undo</button></div>`); el.replaceWith(g); enter(g);
      const tm = setTimeout(() => { g.classList.add('leave'); setTimeout(() => g.remove(), 320); }, 4000);
      $('button', g).onclick = () => { clearTimeout(tm); M.splice(i, 0, m); count(); const n = item(m); g.replaceWith(n); enter(n); }; };
    return el;
  }
  function paint(){ list.innerHTML = ''; M.filter(m => f === 'all' || m.k === f).forEach(m => list.appendChild(item(m))); stagger([...list.children], 40); }
  // a row that arrives opens its own height, so the panel grows smoothly instead of jumping
  const grow = el => { if (REDUCE) return; const cs = getComputedStyle(el), gap = parseFloat(getComputedStyle(list).rowGap) || 0, ease = getComputedStyle(r).getPropertyValue('--ease').trim() || 'ease';
    el.animate([{ height:'0px', paddingTop:'0px', paddingBottom:'0px', marginBottom:-gap + 'px', opacity:0, filter:'blur(4px)', overflow:'hidden' }, { height:cs.height, paddingTop:cs.paddingTop, paddingBottom:cs.paddingBottom, marginBottom:'0px', opacity:1, filter:'blur(0px)', overflow:'hidden' }], { duration:560, easing:ease }); };
  seg($('.mmx-tab', r), v => { f = v; paint(); });
  paint();
  // the new memory's highlight and fresh source live in its data, so switching tabs while it is new keeps them
  c.later(2200, () => { const m = { id:nid++, k:'brand', t:'Use “Start free” instead of “Sign up” on CTAs', s:'Learned just now from your edit', isNew:true }; M.unshift(m); count(); if (f === 'brand' || f === 'all'){ const el = item(m); list.prepend(el); grow(el); }
    c.later(2600, () => { m.isNew = false; if (m.s === 'Learned just now from your edit') m.s = 'Learned from your edit, today'; const el = $(`.mmx-m[data-id="${m.id}"]`, list); if (el){ el.classList.remove('new'); const src = $('.src', el); if (src) src.textContent = m.s; } }); });
});

