.stx-ok .k{fill:none;stroke:#fff;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:24}
.stx-ok::after{content:"";position:absolute;inset:0;border-radius:50%;pointer-events:none}
.stx-dn.go .stx-ok .c{animation:stxpop .6s var(--ease) both}
