/* ---------- Agent harness ---------- */
/* a whole agent app in one card: chats down the side, tabs across the top, a New chat home with suggestions, and the
   conversations themselves, told with the components above */
.card.wide .stage-in:has(>.ahx){max-width:960px}
.ahx{display:flex;height:620px;overflow:hidden;container:ahx/inline-size;text-align:left;position:relative}
