.ahx-nav,.ahx-cv{display:flex;align-items:center;gap:9px;width:100%;min-height:32px;padding:0 9px;border-radius:9px;font-size:13px;text-align:left;color:var(--fg2);transition:background var(--t-fast),box-shadow var(--t-fast),color var(--t-fast)}
