.ahx-si{display:block;width:100%;height:30px;margin:4px 0 6px;padding:0 10px;border:0;border-radius:9px;background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);font-size:12.5px;outline:0;transition:box-shadow var(--t-fast)}
.ahx-si:focus{box-shadow:inset 0 0 0 1px var(--rail)}
.ahx-si::placeholder{color:var(--muted)}
.ahx-si::-webkit-search-cancel-button{display:none}
.ahx-list{flex:1;min-height:0;display:flex;flex-direction:column;gap:2px;overflow-y:auto;scrollbar-width:none}
.ahx-none{margin:0;padding:6px 9px;font-size:12.5px;color:var(--muted)}
.ahx-mk{display:grid;place-items:center;width:10px;flex:none}
.ahx-mk:empty{display:none}
.ahx-mk .spin{width:10px;height:10px;color:var(--muted)}
.ahx-main{flex:1;min-width:0;display:flex;flex-direction:column;position:relative;container:ahm/inline-size}
/* the tabs: a chat opens or comes to the front, × closes it, + opens New chat */
.ahx-top{flex:none;display:flex;align-items:center;gap:4px;height:46px;padding:0 10px 0 8px;border-bottom:1px solid var(--line)}
.ahx-menu{display:none}
.ahx.ns .ahx-menu{display:inline-grid}
.ahx-tabs{position:relative;display:flex;align-items:center;gap:2px;min-width:0;padding:2px;overflow-x:auto;scrollbar-width:none}
