.ahx-tab{flex:0 1 164px;min-width:108px;display:flex;align-items:center;height:30px;border-radius:9px;overflow:hidden;color:var(--fg2);transition:background var(--t-fast),box-shadow var(--t-fast),color var(--t-fast)}
.ahx-tab:hover{background:var(--row);color:var(--fg)}
.ahx-tab.on{background:var(--surface);color:var(--fg);box-shadow:inset 0 0 0 1px var(--rail),0 1px 2px rgba(0,0,0,.04)}
.ahx-tb{flex:1;min-width:0;display:flex;align-items:center;gap:7px;height:100%;padding:0 2px 0 10px;font-size:12.5px;text-align:left}
