.ahx-spl .spl-in{gap:7px;padding:0 4px 0 11px;font-size:12.5px}
.ahx-spl .spl-in .g{width:14px}
.ahx-spl .spl-in .pill{height:22px;padding:0 9px;margin-left:1px;font-size:12px}
/* New chat: a greeting, the composer and three suggestions, in the middle of the card */
.ahx-body{flex:1;min-height:0;display:flex;flex-direction:column;position:relative}
.ahx-home{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;padding:20px 28px 44px}
.ahx-main:not(.home) .ahx-home{display:none}
.ahx-main.home :is(.ahx-feed,.ahx-bot){visibility:hidden}
.ahx-hw{width:100%;max-width:600px;margin:0 auto;display:flex;flex-direction:column;gap:14px}
.ahx-hi{display:flex;flex-direction:column;padding:0 4px;margin-bottom:6px;font-size:14px;font-weight:500;letter-spacing:-.4px;line-height:1.3}
.ahx-hi span{color:var(--muted)}
.ahx-hi h4{margin:0;font:inherit;color:var(--fg)}
.ahx-sg{display:flex;flex-direction:column;gap:1px;margin-top:4px}
.ahx-sr{display:flex;align-items:center;gap:11px;width:100%;min-height:36px;padding:0 10px;border-radius:10px;font-size:13.5px;color:var(--fg);text-align:left;transition:background var(--t-fast)}
.ahx-sr:hover{background:var(--row)}
.ahx-sr .i{color:var(--muted)}
.ahx-hf{display:flex;padding-left:3px}
.ahx-shf{color:var(--muted)}
.ahx-shf .i{transition:transform .6s var(--ease)}
.ahx-shf:hover .i{transform:rotate(-180deg)}
/* a chat scrolls inside the card; each one keeps its own column, only the one on screen takes up room */
.ahx-feed{flex:1;min-height:0;display:flex;flex-direction:column;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.ahx-cols{flex:1 0 auto;display:grid}
.ahx-col{grid-area:1/1;min-width:0;width:100%;max-width:688px;margin:0 auto;display:flex;flex-direction:column;gap:20px;padding:24px 28px 30px;transition:opacity var(--t) var(--ease)}
.ahx-col.off{visibility:hidden;height:0;padding-block:0;overflow:hidden}
.ahx-col.ff{opacity:0}
.ahx-say .w{animation:lvw .5s var(--ease) both}
.ahx-fs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px}
.ahx-fs:last-child{margin-bottom:0}
.ahx-msg{min-width:0}
/* a component in the chat lines up with the messages on the left, instead of centring itself as it does on its own */
.ahx-col .ahx-msg>*{margin-left:0;margin-right:auto}
/* chat components sit on the chat itself, the way a bare card shows them; an artifact and a diff keep their card */
.ahx-msg:not(.box)>.panel:not(.keep){background:none;box-shadow:none;padding-left:0;padding-right:0;border-radius:0}
/* in the chat a finished question set closes up behind its answers */
.ahx-msg .dpx-body{min-height:0}
.ahx-msg .dpx-f.leave{display:none}
/* the agent's work, gathered under one line that folds away when it is done */
.ahx-wk{display:flex;flex-direction:column;align-items:flex-start}
.ahx-wh{display:inline-flex;align-items:center;gap:8px;height:28px;padding:0 9px 0 7px;margin-left:-7px;border-radius:var(--r-pill);font-size:13.5px;color:var(--fg2);transition:background var(--t-fast),color var(--t-fast)}
.ahx-wh:hover{background:var(--row);color:var(--fg)}
.ahx-wh .g{display:grid;place-items:center;width:14px;color:var(--muted)}
.ahx-wh .m{color:var(--muted);font-size:12.5px}
.ahx-wh>.i{color:var(--muted);transition:transform var(--t) var(--ease)}
.ahx-wh[aria-expanded="true"]>.i{transform:rotate(180deg)}
.ahx-wb{align-self:stretch}
.ahx-wl{display:flex;flex-direction:column;gap:16px;margin:8px 0 2px 6px;padding-left:18px;border-left:1px solid var(--line)}
.ahx-bot{flex:none;position:relative;padding:0 24px 18px}
.ahx-bot::before{content:"";position:absolute;left:0;right:10px;bottom:100%;height:28px;background:linear-gradient(transparent,var(--surface));pointer-events:none}
.ahx-bot .cpx{max-width:632px;margin:0 auto}
.ahx .cpx-thread{display:none}
.ahx .ctm-ft{gap:2px;margin-right:1px;font-size:12.5px}
.ahx .ctm-ft>span{color:var(--muted);margin-right:2px}
/* while the agent works in the chat on screen, a new message waits */
.ahx.busy .cpx-bar .cpx-send{background:var(--rail);color:var(--surface);pointer-events:none}
/* the panel beside the chat, for an artifact */
.ahx-pane{flex:none;width:0;overflow:hidden;background:var(--surface);border-left:1px solid transparent;transition:width var(--t) var(--ease),border-color var(--t) var(--ease)}
.ahx.pn .ahx-pane{width:300px;border-left-color:var(--line)}
.ahx-pi{width:300px;height:100%;display:flex;flex-direction:column}
.ahx-ph{flex:none;display:flex;align-items:center;gap:8px;height:46px;padding:0 8px 0 14px;border-bottom:1px solid var(--line);font-size:13px;font-weight:500}
.ahx-ph .t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ahx-ph>.i{color:var(--pb)}
.ahx-ph .ib{width:28px;height:28px;color:var(--muted)}
.ahx-ph .ib:hover{color:var(--fg)}
.ahx-pb{flex:1;min-height:0;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:16px;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.ahx-pn{display:flex;flex-direction:column;gap:4px;font-size:13px;line-height:1.55;color:var(--fg2)}
.ahx-pn b{font-weight:500;color:var(--fg)}
.ahx-pn p{margin:0 0 10px}
.ahx-scrim{display:none}
/* a narrow chat, beside the panel or on a phone: the composer keeps only what it needs */
@container ahm (max-width:560px){
  .ahx .ctm-ft>span,.ahx .cpx-bar .cpx-ctx,.ahx-spl .spl-in .m{display:none}
}
/* phone: the chats slide in from the side, the tabs scroll, the panel covers the chat */
@container ahx (max-width:620px){
  .ahx .ahx-side,.ahx.ns .ahx-side{position:absolute;z-index:6;left:0;top:0;bottom:0;width:244px;margin-left:0;background:var(--surface);transform:translateX(-101%)}
  .ahx.dr .ahx-side{transform:none;box-shadow:var(--shadow-pop)}
  .ahx-scrim{display:block;position:absolute;inset:0;z-index:5;background:rgba(0,0,0,.2);opacity:0;pointer-events:none;transition:opacity var(--t) var(--ease)}
  .ahx.dr .ahx-scrim{opacity:1;pointer-events:auto}
  .ahx .ahx-menu{display:inline-grid}
  .ahx-top{padding:0 6px}
  .ahx-spl{display:none}
  .ahx-tab{flex-basis:150px;min-width:96px}
  .ahx-tab:not(.on) .ahx-tx{display:none}
  .ahx-home{padding:16px 14px 28px}
  .ahx-hi{font-size:14px}
  .ahx-col{padding:18px 16px 24px}
  .ahx-bot{padding:0 10px 10px}
  .ahx-pane{position:absolute;z-index:4;top:0;right:0;bottom:0;border-left:0}
  .ahx.pn .ahx-pane{width:100%}
  .ahx-pi{width:100%}
}

