DM.def('kanban', (r, c) => {
  const COLS = [['todo','To do'],['doing','In progress'],['done','Done']];
  let K = [
    { id:1, c:'todo', t:'Audit checkout for contrast', tag:['b','Design'], who:['DA','var(--pb)'] },
    { id:2, c:'todo', t:'Write release notes for pricing', tag:['l','Copy'], who:['MK','var(--pl)'] },
    { id:3, c:'todo', t:'Rename layers in Hero', tag:['b','Design'], who:['DA','var(--pb)'] },
    { id:4, c:'doing', t:'Export tokens to CSS', tag:['m','Code'], who:['DA','var(--pb)'], run:.4 },
    { id:5, c:'doing', t:'Review annual plan copy', tag:['l','Copy'], who:['JO','var(--pm)'] },
    { id:6, c:'done', t:'One CTA per pricing card', tag:['b','Design'], who:['MK','var(--pl)'] }
  ];
  // the agent's timer repaints the board, so it waits while a card is dragged or a new title is typed
  const wrap = $('.kbx-cols', r); let dragging = false, editing = false;
  wrap.innerHTML = COLS.map(cl => `<div class="kbx-c" data-c="${cl[0]}"><div class="kbx-ch"><b>${cl[1]}</b><span class="n num"></span><button class="ib" aria-label="Add card" data-tip="Add card">${I('plus','xs')}</button></div><div class="kbx-list"></div></div>`).join('');
