DM.def('artifact-card', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{doc}', I('file-text')).replace('{link}', I('link')).replace('{ext}', I('ext'));
  const M = ['April','May','June','July','August','September'];
  const V = [
    { p:'First pass at churn by month, sources still to check.', b:[3.4,3.9,4.3,4.1,3.8,3.6], sub:'v1, edited yesterday', note:'First draft' },
    { p:'Churn rose in July, the spike lines up with the pricing change.', b:[3.4,3.9,4.1,5.8,4.7,3.9], sub:'v2, edited 1 hour ago', note:'Added the July spike' },
    { p:'Churn rose in July, then settled once onboarding emails went out.', b:[3.4,3.9,4.1,5.8,4.5,3.1], sub:'v3, edited 2 min ago', note:'Final, with your fixes' }
  ];
  const ln = $('.afx-ch .ln', r), ar = $('.afx-ch .ar', r);
  /* a smooth line through the monthly values, redrawn as versions change */
  const xy = b => b.map((v, k) => [k / (b.length - 1) * 300, 52 - (v - 2.6) / 3.6 * 46]);
  const path = p => p.reduce((d, q, k, a) => { if (!k) return `M${q[0]} ${q[1]}`; const p0 = a[k - 2] || a[k - 1], p1 = a[k - 1], p3 = a[k + 1] || q, t = .18; return d + ` C${p1[0] + (q[0] - p0[0]) * t} ${p1[1] + (q[1] - p0[1]) * t} ${q[0] - (p3[0] - p1[0]) * t} ${q[1] - (p3[1] - p1[1]) * t} ${q[0]} ${q[1]}`; }, '');
  let shown = V[2].b.map(() => 3.2), cur = 2;
  const draw = b => { const d = path(xy(b)); ln.setAttribute('d', d); ar.setAttribute('d', d + ' L300 56 L0 56 Z'); };
  function show(i, quiet){ cur = i; const v = V[i], from = shown.slice(), last = v.b[v.b.length - 1], top = Math.max(...v.b), at = v.b.indexOf(top);
    // quiet sets the text straight away, for the first version while the card comes in
    const put = quiet ? (el, t) => { el.textContent = t; } : swap;
    put($('.afx-dp', r), v.p); put($('.afx-sub', r), v.sub); put($('.afx-note', r), v.note);
    put($('.afx-v', r), last.toFixed(1) + '%'); put($('.afx-d', r), '−' + (top - last).toFixed(1) + ' pts since ' + M[at]);
    tween(0, 1, 700, t => { shown = from.map((f, k) => f + (v.b[k] - f) * t); draw(shown); }); }
  draw(shown);
  seg($('.seg2', r), v => show(+v));
  const lk = $('.afx-link', r);
  lk.onclick = () => copied(lk, 'https://designme.dev/a/churn-q3');
  // the agent's versions play through once, first draft to final, unless someone picks one first
  let touched = false; c.on(r, 'pointerdown', () => { touched = true; }, true);
  const vb = $$('.afx-vers .seg2 button', r), pickV = i => { if (!touched && cur !== i) vb[i].click(); };
  vb.forEach((b, i) => b.setAttribute('aria-pressed', i === 0));
  show(0, true); c.later(2300, () => pickV(1)); c.later(4100, () => pickV(2));
});

