/* ---------- Answer action bar ---------- */
/* every action on an answer in one raised rail under it: copy, regenerate with its versions, thumbs, and read aloud, which
   widens into a progress bar and a clock and lights each word as it reads it */
.aab{display:flex;flex-direction:column;gap:12px}
.aab-t{min-height:78px}
.aab-t .w{transition:background .16s,color .16s;border-radius:4px}
.aab-t .w.in{animation:aabw .42s var(--ease) both}
@keyframes aabw{from{opacity:0;filter:blur(4px)}to{opacity:1;filter:none}}
.aab-t.out{animation:aabo .32s var(--ease) both}
@keyframes aabo{to{opacity:0;filter:blur(4px);transform:translateY(-2px)}}
.aab-t .nw{background:var(--hl-ok);border-radius:0}
.aab-t .w.rd{background:var(--accent-bg);color:var(--accent-fg,var(--accent))}
.aab-row{display:flex;align-items:center;flex-wrap:wrap;gap:8px 12px}
.aab-bar{display:inline-flex;align-items:center;gap:1px;padding:3px;border-radius:var(--r-pill);background:var(--surface);box-shadow:var(--shadow)}
.aab-bar .ib{width:28px;height:28px}
.aab-bar .ib[disabled]{opacity:.3;pointer-events:none}
.aab-bar .ib svg{transition:transform .42s var(--ease)}
.aab-re.go svg{transform:rotate(360deg)}
.aab-up[aria-pressed="true"]{color:var(--ok);background:var(--ok-bg)}
.aab-dn[aria-pressed="true"]{color:var(--bad);background:var(--bad-bg)}
.aab-up[aria-pressed="true"] svg,.aab-dn[aria-pressed="true"] svg{transform:scale(1.1) rotate(-8deg)}
.aab-sep{width:1px;height:16px;background:var(--line);margin:0 4px}
/* the version pager only takes room once there is a second version */
.aab-pg{display:inline-flex;align-items:center;max-width:0;overflow:hidden;opacity:0;transition:max-width .42s var(--ease),opacity .32s}
.aab-pg.on{max-width:96px;opacity:1}
.aab-pg .ib{width:24px;height:24px}
.aab-n{font-size:12px;color:var(--muted);min-width:32px;text-align:center}
.aab-rd{display:inline-flex;align-items:center;height:28px;padding:0 7px;border-radius:var(--r-pill);color:var(--fg2);transition:background .16s,color .16s}
.aab-rd:hover{background:var(--hover)}
.aab-rd .ic{display:grid;place-items:center;width:14px}
.aab-rd[aria-pressed="true"]{background:var(--accent-bg);color:var(--accent-fg,var(--accent))}
.aab-rd.paused{background:var(--chip);color:var(--fg2)}
.aab-pr{width:0;height:3px;border-radius:2px;background:color-mix(in srgb,currentColor 22%,transparent);overflow:hidden;margin-left:0;transition:width .42s var(--ease),margin .42s var(--ease)}
.aab-pr i{display:block;height:100%;width:0;background:currentColor;border-radius:inherit}
.aab-tm{font-size:11.5px;max-width:0;overflow:hidden;white-space:nowrap;transition:max-width .42s var(--ease),margin .42s var(--ease)}
.aab-rd.on .aab-pr{width:56px;margin-left:8px}
.aab-rd.on .aab-tm{max-width:80px;margin-left:8px}
.aab-meta{font-size:12px}
.aab-wy{display:flex;flex-direction:column;gap:8px;padding:2px 0 4px}
.aab-wq{font-size:13px;font-weight:500}
.aab-ch{display:flex;flex-wrap:wrap;gap:6px}
.aab-ch .chip.on{background:var(--sel);color:var(--accent-fg,var(--accent));box-shadow:none}
.aab-st{margin:0;min-height:20px;font-size:12.5px;display:flex;align-items:center;gap:6px}
.aab-st.warn{color:var(--warn)}
.aab-st.ok svg{color:var(--ok);flex:none}
@media (max-width:480px){.aab-rd.on .aab-tm{display:none}.aab-rd.on .aab-pr{width:40px}}

