/* ---------- Inline text diff ---------- */
/* a piece of copy with the agent's edits marked inline, struck and added; each edit opens a small toolbar to accept or
   reject it, and an edit the agent isn't sure of says why */
.itd{position:relative;width:100%;max-width:440px;margin:0 auto;padding:16px;display:flex;flex-direction:column;gap:12px}
.itd-h{display:flex;align-items:center;gap:12px}
.itd-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.itd-ht b{font-weight:500;font-size:14px}
.itd-st{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.itd-a{display:flex;gap:6px;flex:none}
.itd-t{margin:0;font-size:14px;line-height:1.8;color:var(--fg)}
.itd-c{padding:2px 1px;border-radius:5px;cursor:pointer;outline:0;transition:background .16s;-webkit-box-decoration-break:clone;box-decoration-break:clone}
.itd-c:hover,.itd-c.on{background:var(--row)}
.itd-c:focus-visible{box-shadow:0 0 0 2px var(--accent-bg)}
.itd-c del{color:var(--del);text-decoration:line-through;text-decoration-thickness:1px;background:color-mix(in srgb,var(--del) 9%,transparent);border-radius:3px;padding:0 2px}
.itd-c ins{color:var(--add);text-decoration:none;background:color-mix(in srgb,var(--add) 11%,transparent);border-radius:3px;padding:0 2px;margin-left:3px}
.itd-c.unsure ins{color:var(--warn);background:var(--warn-bg)}
.itd-c.acc del,.itd-c.rej ins{display:none}
.itd-c.acc ins,.itd-c.rej del{color:inherit;background:none;text-decoration:none;margin:0;padding:0}
.itd-bar{position:absolute;left:0;top:0;z-index:5;display:flex;flex-direction:column;gap:8px;padding:8px;width:max-content;max-width:260px;border-radius:12px;background:var(--raised);box-shadow:var(--shadow-pop);opacity:0;transform:translateY(-4px);visibility:hidden;pointer-events:none;transition:opacity .16s,transform .32s var(--ease),visibility 0s .32s}
.itd-bar.open{opacity:1;transform:none;visibility:visible;pointer-events:auto;transition-delay:0s}
.itd-why{margin:0;display:flex;gap:6px;font-size:13px;line-height:1.45;color:var(--warn)}
.itd-why svg{flex:none;margin-top:3px}
.itd-bb{display:flex;gap:6px}
.itd-f{margin:0;display:flex;align-items:center;gap:6px;font-size:13px;min-height:20px}
.itd-f svg{color:var(--ok)}

