DM.def('inline-text-diff', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chk}', I('check','xs')).replace('{x}', I('x','xs')).replace('{warn}', I('alert','xs'));
  // the copy, and the agent's edits to it: what it said, what the agent suggests, and why, when the agent isn't sure
  const T = [{ o:'Pick', n:'Choose' }, ' a plan that ', { o:'fits your team', n:'grows with your studio' }, '. Every plan ', { o:'includes', n:'comes with' }, ' unlimited projects, and ', { o:'you can cancel at any time', n:'your first month is free', why:'Not in the pricing brief: there is no free month' }, '.'];
  const E = T.filter(x => typeof x === 'object');
  const root = $('.itd', r), tx = $('.itd-t', r), st = $('.itd-st', r), bar = $('.itd-bar', r), why = $('.itd-why', r), f = $('.itd-f', r), acts = $('.itd-a', r);
  tx.innerHTML = T.map(x => typeof x === 'string' ? x : `<span class="itd-c${x.why ? ' unsure' : ''}" role="button" tabindex="0" aria-haspopup="dialog" aria-expanded="false"><del>${x.o}</del><ins>${x.n}</ins></span>`).join('');
  const chunks = $$('.itd-c', tx);
  E.forEach((e, i) => { e.s = ''; chunks[i].setAttribute('aria-label', `Edit ${i + 1} of ${E.length}: ${e.o}, suggested ${e.n}`); });
  let cur = -1;
  function tally(){
    const n = E.filter(e => !e.s).length, a = E.filter(e => e.s === 'acc').length;
    swap(st, n === E.length ? `${n} edits to review` : n ? `${n} of ${E.length} left` : `${a} accepted, ${E.length - a} rejected`);
    if (!n && !f.textContent){ acts.hidden = true; f.innerHTML = `${I('ok','xs')}<span>Saved to Pricing v4</span>`; enter(f); }
  }
  const close = () => { bar.classList.remove('open'); bar.inert = true; chunks.forEach(x => { x.classList.remove('on'); x.setAttribute('aria-expanded', false); }); cur = -1; };
  // the toolbar opens under the edit's last line; inside a scaled preview the offsets are divided by its scale
  function open(i){
    cur = i; const el = chunks[i], e = E[i];
    chunks.forEach((x, k) => { x.classList.toggle('on', k === i); x.setAttribute('aria-expanded', k === i); });
    why.hidden = !e.why; $('span', why).textContent = e.why || '';
    const rb = root.getBoundingClientRect(), k = rb.width / root.offsetWidth || 1, rs = el.getClientRects(), cr = rs[rs.length - 1] || el.getBoundingClientRect();
    bar.inert = false; bar.classList.add('open');
    bar.style.left = Math.max(12, Math.min((cr.left - rb.left) / k, root.offsetWidth - bar.offsetWidth - 12)) + 'px';
    bar.style.top = ((cr.bottom - rb.top) / k + 6) + 'px';
  }
  function decide(i, s){ E[i].s = s; chunks[i].classList.remove('acc', 'rej'); chunks[i].classList.add(s); tally(); }
  // a click anywhere else on the page can close the toolbar between the story's taps, and then there is no edit to decide
  const pick = s => { const i = cur; if (i < 0) return; const back = bar.contains(document.activeElement); close(); decide(i, s); if (back) chunks[i].focus({ preventScroll:true }); };
  chunks.forEach((el, i) => { el.onclick = () => cur === i ? close() : open(i); el.onkeydown = ev => { if (ev.key === 'Enter' || ev.key === ' '){ ev.preventDefault(); el.click(); } }; });
  $('.itd-acc', r).onclick = () => pick('acc');
  $('.itd-rej', r).onclick = () => pick('rej');
  $('.itd-ok', r).onclick = () => { close(); E.forEach((e, i) => { if (!e.s) decide(i, 'acc'); }); };
  $('.itd-no', r).onclick = () => { close(); E.forEach((e, i) => { if (!e.s) decide(i, 'rej'); }); };
  // Escape or a click elsewhere closes the toolbar
  c.on(r, 'keydown', ev => { if (ev.key === 'Escape' && cur >= 0){ const el = chunks[cur]; close(); el.focus({ preventScroll:true }); } });
  c.on(document, 'pointerdown', ev => { if (cur >= 0 && !bar.contains(ev.target) && !ev.target.closest('.itd-c')) close(); });
  bar.inert = true; tally();
  // the preview's story: accept two edits, read why the agent isn't sure of one and reject it, then accept the rest
  c.story(async s => {
    await s.beat(4);
    await s.tap(chunks[0]); await s.beat(2); await s.tap($('.itd-acc', r)); await s.beat(1);
    await s.tap(chunks[1]); await s.beat(2); await s.tap($('.itd-acc', r)); await s.beat(1);
    await s.tap(chunks[3]); await s.beat(5); await s.tap($('.itd-rej', r)); await s.beat(3);
    await s.tap($('.itd-ok', r)); s.away();
    await s.beat(3);
  });
});

c121.css:
/* ---------- Draft review ---------- */
/* what the agent wrote, laid out like the email it is: who it goes to, the subject, the message and what is attached,
   then send now or later, or discard. Before sending it checks for an attachment the message mentions, and after
   sending there is a short window to undo */
.drf{position:relative;width:100%;max-width:440px;margin:0 auto;padding:16px;display:flex;flex-direction:column;gap:12px}
.drf-h{display:flex;align-items:center;gap:12px}
.drf-ag{width:32px;height:32px;border-radius:9px;background:var(--chip);color:var(--fg2);display:grid;place-items:center;flex:none}
.drf-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.drf-ht b{font-weight:500;font-size:14px}
.drf-ht span{font-size:13px}
.drf-fs{display:flex;flex-direction:column;border-top:1px solid var(--line)}
.drf-r{display:flex;align-items:center;gap:10px;min-height:40px;border-bottom:1px solid var(--line);font-size:13.5px}
.drf-l{width:52px;flex:none;color:var(--muted);font-size:13px}
.drf-p{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px 0 3px;border-radius:var(--r-pill);background:var(--chip);font-size:13px}
.drf-p .av{width:20px;height:20px;font-size:9px}
.drf-s{flex:1;min-width:0;height:38px;padding:0;border:0;background:none;outline:0;font:inherit;font-size:13.5px;color:var(--fg)}
.drf-b{font-size:14px;line-height:1.6;color:var(--fg);outline:0;border-radius:6px}
.drf-b:focus-visible{box-shadow:0 0 0 2px var(--accent-bg)}
.drf-att{display:flex;flex-wrap:wrap;gap:6px}
.drf-att:empty{display:none}
.drf-file{display:inline-flex;align-items:center;gap:8px;height:30px;padding:0 10px;border-radius:8px;background:var(--chip);font-size:13px}
.drf-file>svg{color:var(--fg2)}
.drf-file .muted{font-size:12px;display:inline-flex;align-items:center}
.drf-file .spin{width:10px;height:10px}
/* the shut warning is hidden once it has folded away, so nothing measures the clipped part as if it were drawn */
.drf-wf.shut>div{visibility:hidden;transition:visibility 0s var(--t)}
.drf-w{padding:10px 12px;border-radius:12px;background:var(--warn-bg);display:flex;flex-direction:column;gap:10px}
.drf-w p{margin:0;display:flex;gap:8px;font-size:13px;line-height:1.45;color:var(--fg)}
.drf-w p svg{color:var(--warn);flex:none;margin-top:3px}
.drf-wa{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:6px}
.drf-w .pill.ghost{background:var(--surface);color:var(--fg);box-shadow:var(--shadow)}
/* a hairline sets the buttons apart from the message, as in a mail composer */
.drf-f{display:flex;align-items:center;gap:8px;padding-top:12px;border-top:1px solid var(--line)}
.drf-f .sp{flex:1}
.drf-when{font-size:13px}
.drf-mg{display:flex;gap:1px;flex:none}
.drf-go{border-radius:999px 0 0 999px;padding-right:12px}
.drf-dd{border-radius:0 999px 999px 0;padding:0 9px}
.drf-pop{min-width:220px}
.drf.sent .drf-fs,.drf.sent .drf-b,.drf.sent .drf-att{opacity:.55;transition:opacity .32s}
.drf-done{display:flex;align-items:center;gap:12px;padding:10px 10px 10px 12px;border-radius:12px;background:var(--ok-bg);font-size:13.5px}
.drf-done.bin{background:var(--chip)}
.drf-done.later{background:var(--pb-bg)}
.drf-done>svg{color:var(--ok);flex:none}
.drf-done.bin>svg,.drf-done.later>svg{color:var(--fg2)}
.drf-done .t{flex:1;min-width:0;display:flex;flex-direction:column}
.drf-done .t span{font-size:13px}
.drf-done .t .muted{color:var(--fg2)}
.drf-done .pill{background:var(--surface);color:var(--fg);box-shadow:var(--shadow)}
.drf-done .pill:hover{box-shadow:var(--shadow-pop)}

