/* ---------- Agent inbox ---------- */
/* every run in one list, grouped by what it needs: Needs you, Running, Done. A run glides to its new group when it moves */
.aib{width:100%;max-width:440px;margin:0 auto;padding:6px}
.aib-h{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:8px 10px 6px}
.aib-h b{font-weight:500;font-size:14px}
.aib-st{font-size:12.5px}
.aib-g{display:flex;flex-direction:column}
.aib-gh{display:flex;align-items:center;gap:8px;padding:12px 10px 4px;font-size:12px;color:var(--muted)}
.aib-gh .n{font-variant-numeric:tabular-nums}
.aib-gl{display:flex;flex-direction:column}
.aib-i{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:10px;font-size:13px;transition:background .16s}
.aib-i:hover{background:var(--row)}
.aib-i.mv{position:relative;z-index:1;background:var(--surface);box-shadow:var(--shadow)}
.aib-i.mv.fail{background:var(--bad-bg)}
.aib-av{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;flex:none;font-size:11px;font-weight:500}
.aib-t{flex:1;min-width:0;display:flex;flex-direction:column}
.aib-t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aib-t span{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aib-i.fail .aib-t span{color:var(--bad)}
.aib-r{display:flex;align-items:center;gap:6px;flex:none;font-size:12.5px;color:var(--fg2)}
.aib-r .spin{width:11px;height:11px;color:var(--accent-fg,var(--accent))}
.aib-r .ok{color:var(--ok);display:grid}
.aib-i.fail{background:var(--bad-bg)}
.aib-i.fail .aib-r .pill{background:var(--surface);color:var(--fg);box-shadow:var(--shadow)}

