/* ---------- Prompt library ---------- */
/* the studio's saved prompts, each with blanks like {page}. Opening one lays its blanks out as fields, the prompt
   fills in as they change, and it can't be used until every blank has a value */
.plb{position:relative;width:100%;max-width:440px;margin:0 auto;padding:16px}
.plb-list,.plb-one{display:flex;flex-direction:column;gap:12px}
.plb-list[hidden],.plb-one[hidden]{display:none}
.plb-h{display:flex;align-items:center;gap:8px;min-height:32px}
.plb-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.plb-ht b{font-weight:500;font-size:14px}
.plb-ht span{font-size:13px}
.plb-back{margin-left:-6px;flex:none}
.plb-rows{display:flex;flex-direction:column;margin:0 -8px}
.plb-row{display:flex;align-items:center;gap:12px;width:100%;padding:9px 8px;border-radius:12px;text-align:left;color:var(--fg);transition:background var(--t-fast)}
.plb-row:hover{background:var(--row)}
.plb-ic{width:32px;height:32px;border-radius:9px;background:var(--chip);color:var(--fg2);display:grid;place-items:center;flex:none}
.plb-rt{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.plb-rt b{font-weight:500;font-size:13.5px}
.plb-rt>span{font-size:13px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.plb-n{font-size:12px;color:var(--muted);flex:none}
.plb-row>svg:last-child{color:var(--muted);flex:none}
.plb-tp{margin:0;padding:10px 12px;border-radius:12px;background:var(--chip);font-size:14px;line-height:1.8;color:var(--fg)}
.plb-s{padding:2px 5px;border-radius:6px;background:var(--accent-bg);color:var(--accent-fg,var(--accent));-webkit-box-decoration-break:clone;box-decoration-break:clone;transition:background .25s,color .25s,box-shadow .25s}
.plb-s.empty{background:var(--surface);color:var(--muted);box-shadow:inset 0 0 0 1px var(--rail)}
.plb-s.bad{color:var(--bad);box-shadow:inset 0 0 0 1px var(--bad)}
.plb-vars{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
.plb-fd{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500;min-width:0}
.plb-fd.wide{grid-column:1/-1}
.plb-in{width:100%;border:0;outline:0;border-radius:11px;background:var(--chip);height:38px;padding:0 12px;font:inherit;font-size:13.5px;font-weight:400;color:var(--fg);transition:box-shadow .25s,background .25s}
.plb-in::placeholder{color:var(--muted)}
.plb-in:focus,.plb-in.ed{background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--accent-mark,var(--accent)),0 0 0 4px var(--accent-bg)}
.plb-fd.bad .plb-in{box-shadow:inset 0 0 0 1.5px var(--bad)}
.plb-er{font-size:12px;color:var(--bad);font-weight:400}
.plb-er[hidden]{display:none}
.plb-sel{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;height:38px;padding:0 10px 0 12px;border-radius:11px;background:var(--chip);font-size:13.5px;font-weight:400;color:var(--fg);text-align:left;transition:background .2s,box-shadow .2s}
.plb-sel:hover{background:var(--row)}
.plb-sel[aria-expanded="true"]{background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--accent-mark,var(--accent)),0 0 0 4px var(--accent-bg)}
.plb-sel>svg{color:var(--muted);flex:none;transition:transform .32s var(--ease)}
.plb-sel[aria-expanded="true"]>svg{transform:rotate(180deg)}
.plb-pop{min-width:180px}
.plb-f{display:flex;align-items:center;gap:8px;min-height:32px}
.plb-f .sp{flex:1}
.plb-note{font-size:13px}
.plb-done{display:flex;align-items:center;gap:12px;padding:10px 10px 10px 12px;border-radius:12px;background:var(--ok-bg);font-size:13.5px}
.plb-done>svg{color:var(--ok);flex:none}
.plb-done .t{flex:1;min-width:0;display:flex;flex-direction:column}
.plb-done .t span{font-size:13px}
.plb-done .t .muted{color:var(--fg2)}
.plb-done .pill{background:var(--surface);color:var(--fg);box-shadow:var(--shadow)}
.plb-one.used .plb-vars{opacity:.55;transition:opacity .32s}

