/* ---------- Eval results ---------- */
/* an eval suite's latest run: one bar segment per case, the pass count against the run before, and the cases, all or
   just the failed ones. A failed case opens to show what was expected and what came back, with a fix that reruns it */
.evr{width:100%;max-width:440px;margin:0 auto;padding:6px;display:flex;flex-direction:column}
.evr-h{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 10px 10px}
.evr-ht{display:flex;flex-direction:column;min-width:0}
.evr-ht b{font-weight:500;font-size:14px}
.evr-st{font-size:12.5px}
.evr-run{flex:none}
.evr-run .spin{width:10px;height:10px}
.evr-sum{display:flex;flex-direction:column;gap:8px;padding:12px 10px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.evr-segs{display:flex;gap:3px}
.evr-segs i{flex:1;height:6px;border-radius:3px;background:var(--rail);transition:background .3s}
.evr-segs i.pass{background:var(--ok)}
.evr-segs i.fail{background:var(--bad)}
.evr-segs i.run{background:var(--accent-mark,var(--accent));animation:evrrun 1s ease-in-out infinite}
@keyframes evrrun{50%{opacity:.4}}
.evr-nums{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:20px;font-size:13px}
.evr-dl:empty{display:none}
.evr-tabs{padding:10px 4px 4px}
.evr-tabs .n{color:var(--muted);margin-left:2px}
.evr-tabs .n:empty{display:none}
.evr-list{display:flex;flex-direction:column}
/* a case folds away when the filter hides it, and stays hidden once shut so nothing measures it */
.evr-w.shut>div{visibility:hidden;transition:visibility 0s var(--t)}
.evr-i{display:flex;flex-direction:column;border-radius:10px;transition:background .2s}
.evr-r{display:flex;align-items:center;gap:10px;width:100%;min-height:38px;padding:6px 10px;border-radius:10px;font-size:13px;text-align:left;color:var(--fg)}
.evr-g{width:16px;height:16px;display:grid;place-items:center;flex:none;color:var(--faint)}
.evr-g .spin{width:11px;height:11px;color:var(--accent-fg,var(--accent))}
.evr-i.pass .evr-g{color:var(--ok)}
.evr-i.fail .evr-g{color:var(--bad)}
.evr-n{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.evr-i.queued .evr-n{color:var(--fg2)}
.evr-tm{font-size:12px;color:var(--muted)}
.evr-ch{display:grid;color:var(--muted)}
.evr-ch svg{transition:transform .32s var(--ease)}
.evr-r[aria-expanded="false"] .evr-ch svg{transform:rotate(-90deg)}
.evr-i.fail{background:var(--bad-bg)}.evr-i.fail :is(.evr-tm,.evr-kv .k){color:var(--fg2)}
.evr-d.shut>div{visibility:hidden;transition:visibility 0s var(--t)}
.evr-dd{display:flex;flex-direction:column;gap:4px;padding:0 10px 10px 36px;font-size:12.5px}
.evr-kv{display:flex;gap:8px}
.evr-kv .k{width:58px;flex:none;color:var(--muted)}
.evr-kv .bad{color:var(--bad)}
.evr-fix{align-self:flex-start;margin-top:6px;background:var(--surface);color:var(--fg);box-shadow:var(--shadow)}
.evr-fix:hover{background:var(--surface);box-shadow:var(--shadow-pop)}
