/* ---------- Scheduled runs ---------- */
/* recurring agent tasks: the schedule in words, when it runs next and how its last run went, with Run now and an on/off
   switch. A paused one dims and says so; one whose last run failed says why and offers the fix */
.shx{padding:12px;display:flex;flex-direction:column;gap:6px}
.shx-h{display:flex;align-items:center;gap:10px;padding:2px 10px 8px}
.shx-h>div{display:flex;flex-direction:column;min-width:0}
.shx-h b{font-weight:500;font-size:13.5px}
.shx-st{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-list{display:flex;flex-direction:column}
.shx-r{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:12px;padding:8px 10px;border-radius:12px;font-size:13px;transition:background .2s}
.shx-r:hover{background:var(--row)}
.shx-r .ic{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;position:relative;align-self:center;transition:opacity .3s}
.shx-r .ic.brandic{background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);color:var(--fg)}
.shx-r .ic .brand{width:15px;height:15px}
.shx-r .ic::after{content:"";position:absolute;right:-2px;bottom:-2px;box-sizing:border-box;width:8px;height:8px;border-radius:50%;background:var(--faint);box-shadow:0 0 0 2px var(--surface);transition:background .3s}
.shx-r[data-st="ok"] .ic::after{background:var(--ok)}
.shx-r[data-st="bad"] .ic::after{background:var(--bad)}
.shx-r[data-st="run"] .ic::after{width:10px;height:10px;right:-3px;bottom:-3px;background:var(--surface);border:1.5px solid var(--accent-mark,var(--accent));border-right-color:transparent;animation:rot .8s linear infinite}
.shx-r.off .ic::after{background:var(--faint)}
/* the name shares its line with Run now and the switch; the schedule and the result below it take the full width */
.shx-r .ic{grid-row:1/4}
.shx-r .t{display:contents}
.shx-r :is(.nm,.d,.res){grid-column:2/-1;transition:color .3s}
.shx-r .nm{grid-column:2}
/* a paused one dims: its tile fades, and its name and result step down to muted, so the text stays readable */
.shx-r.off .ic{opacity:.5}.shx-r.off :is(.nm,.res .i){color:var(--muted)}
.shx-r .nm,.shx-r .d{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-r .d{font-size:12px;color:var(--muted)}
.shx-r .res{display:flex;align-items:center;gap:5px;min-width:0;height:18px;font-size:12px;color:var(--muted)}
.shx-r .res>span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shx-r .res .i{color:var(--ok)}
.shx-r[data-st="bad"] .res,.shx-r[data-st="bad"] .res .i{color:var(--bad)}
.shx-act{grid-column:3;grid-row:1;display:flex;align-items:center;gap:8px;margin-block:-5px}
.shx-run{width:28px;height:28px}
.shx-run:disabled{opacity:.4;background:none;transform:none}
.shx-r .shx-fx{grid-column:2/-1;grid-row:4}
.shx-fx>div{overflow-clip-margin:0}
.shx-fx>div>div{display:flex;flex-wrap:wrap;gap:6px;padding-top:8px}
.shx-add{display:flex;align-items:center;gap:8px;height:30px;padding:0 12px 0 10px;font-size:12.5px;color:var(--fg2);border-radius:var(--r-pill);align-self:flex-start;transition:background-color .2s,color .2s}
.shx-add:hover{color:var(--fg);background:var(--chip)}
.shx-pop{width:272px;padding:12px}
.shx-f{display:flex;flex-direction:column;gap:8px}
.shx-f h4{margin:0 0 2px;font-size:13px;font-weight:500}
.shx-in{width:100%;height:32px;border:0;outline:0;border-radius:10px;background:var(--chip);padding:0 10px;font:inherit;font-size:13px;color:var(--fg);transition:box-shadow .3s}
.shx-in::placeholder{color:var(--muted)}
.shx-in:focus{box-shadow:inset 0 0 0 1px var(--accent-mark,var(--accent)),0 0 0 3px var(--accent-bg)}
.shx-rep{display:flex}
.shx-rep button{flex:1 1 auto;padding:0 8px}
.shx-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px}
.shx-days button{height:28px;border-radius:8px;background:var(--chip);font-size:12px;color:var(--fg2);transition:background .2s,color .2s}
.shx-days button:hover{background:var(--hover);color:var(--fg)}
.shx-days button[aria-pressed="true"]{background:var(--accent-bg);color:var(--accent-fg,var(--accent))}
.shx-ff{display:flex;align-items:center;gap:8px;padding-top:2px}
.shx-sum{flex:1;min-width:0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

