DM.def('segmented-control', (r, c) => {
  const uid = Math.random().toString(36).slice(2, 7);
  const seg = $('.sgc-seg', r), knob = $('.sgc-k', r), tabs = $$('[role="tab"]', seg), panel = $('.sgc-p', r), inner = $('.sgc-in', r), range = $('.sgc-r', r);
  tabs.forEach(t => { t.id = `sgc-${t.dataset.v}-${uid}`; t.setAttribute('aria-controls', 'sgc-p-' + uid); });
  panel.id = 'sgc-p-' + uid;
  // the pricing launch in October 2026, seen as a day, a week or a month. Today is Friday the 23rd
  const DAY = [['09:30', 'Pricing review with Maya', 'Pricing v4, frames 1 to 3', 'var(--pl)'], ['13:00', 'Export tokens to CSS', 'Build agent', 'var(--pm)'], ['16:00', 'Ship pricing v4', 'designme.studio/pricing', 'var(--pb)']];
  // the week: each day's events, earliest first. Friday's are the day above
  const WEEK = [['Mon', 19, [['10:00', 'Kickoff with Maya', 'var(--pl)'], ['15:00', 'Brief the agents', 'var(--pm)']]],
    ['Tue', 20, [['10:00', 'Wireframe review', 'var(--pl)'], ['11:30', 'Copy for the plan cards', 'var(--pt)'], ['14:00', 'Token audit', 'var(--pm)'], ['16:00', 'Stakeholder check-in', 'var(--pb)']]],
    ['Wed', 21, [['11:00', 'Copy pass', 'var(--pt)']]], ['Thu', 22, [['14:00', 'Design QA', 'var(--pb)'], ['16:30', 'Fix contrast issues', 'var(--pm)']]],
    ['Fri', 23, DAY.map(([t, n, , col]) => [t, n, col])], ['Sat', 24, []], ['Sun', 25, []]];
  const BUSY = [2, 6, 7, 9, 13, 14, 15, 16, 19, 20, 21, 22, 23, 27, 28, 29, 30];
  const V = {
    day:['Friday, Oct 23', () => `<div class="sgc-day">${DAY.map(([t, n, d, col]) => `<div class="sgc-ev" style="--c:${col}"><span class="num muted">${t}</span><i></i><span class="t">${n}<span>${d}</span></span></div>`).join('')}</div>`],
    week:['Oct 19 – 25', () => `<div class="sgc-wk">${WEEK.map(([d, n, ev]) => `<div class="sgc-wr${n === 23 ? ' now' : ''}${ev.length ? '' : ' none'}"><span class="d">${d} ${n}</span>${ev.length ? `<span class="e" style="--c:${ev[0][2]}"><i></i><span class="tm num">${ev[0][0]}</span><span>${ev[0][1]}</span></span>${ev.length > 1 ? `<span class="more">+${ev.length - 1} more</span>` : ''}` : '<span class="e">Nothing planned</span>'}</div>`).join('')}</div>`],
    month:['October 2026', () => `<div class="sgc-mo">${['M','T','W','T','F','S','S'].map(w => `<span class="w">${w}</span>`).join('')}${'<span></span>'.repeat(3)}${Array.from({ length:31 }, (_, i) => `<span class="d num${BUSY.includes(i + 1) ? ' e' : ''}${i + 1 === 23 ? ' now' : ''}">${i + 1}</span>`).join('')}</div>`]
  };
  // the knob slides to the picked tab and takes its width
  const place = () => { const t = tabs.find(x => x.getAttribute('aria-selected') === 'true'); knob.style.left = t.offsetLeft + 'px'; knob.style.width = t.offsetWidth + 'px'; };
  let cur = 'day', n = 0;
  function pick(t, focus){
    tabs.forEach(x => { const on = x === t; x.setAttribute('aria-selected', on); x.tabIndex = on ? 0 : -1; });
    panel.setAttribute('aria-labelledby', t.id); place();
    if (focus) t.focus({ preventScroll:true });
    if (t.dataset.v === cur) return; cur = t.dataset.v; const id = ++n;
    swap(range, V[cur][0]);
    inner.classList.add('out');
    c.later(REDUCE ? 0 : 160, () => { if (id !== n) return; inner.innerHTML = V[cur][1](); inner.classList.remove('out'); });
  }
  tabs.forEach(t => t.onclick = () => pick(t));
  // the arrow keys move along the tabs and pick as they go; Home and End jump to the ends
  seg.onkeydown = e => {
    const i = tabs.indexOf(document.activeElement); if (i < 0) return;
    const go = { ArrowRight:i + 1, ArrowLeft:i - 1, Home:0, End:tabs.length - 1 }[e.key]; if (go === undefined) return;
    e.preventDefault(); pick(tabs[(go + tabs.length) % tabs.length], true);
  };
  inner.innerHTML = V.day[1](); pick(tabs[0]);
