  const ro = new ResizeObserver(place); ro.observe(seg); c.offs.push(() => ro.disconnect());
  // the preview's story: look at the week, then the month, then settle on the week
  c.story(async s => {
    await s.beat(3);
    await s.tap(tabs[1]); s.away(); await s.beat(5);
    await s.tap(tabs[2]); s.away(); await s.beat(5);
    await s.tap(tabs[1]); s.away(); await s.beat(3);
  });
});

