      else ch.classList.add('seen');
      const o = val(f.k, f.v), op = F[f.k].ops[+f.neg], text = `${F[f.k].l} ${op} ${o.c || o.l}`;
      $('.op', ch).textContent = op; $('.v', ch).textContent = o.c || o.l;
      $('.op', ch).setAttribute('aria-label', `${text}: change to ${F[f.k].ops[+!f.neg]}`); $('.op', ch).dataset.tip = `Change to ${F[f.k].ops[+!f.neg]}`;
      $('.x', ch).setAttribute('aria-label', `Remove filter ${text}`);
    });
    // the menu shows each field's value, if it has one
    fields.forEach(m => { const f = A.find(x => x.k === m.dataset.k), o = f && val(f.k, f.v); $('.r', m).textContent = o ? (f.neg ? F[f.k].ops[1] + ' ' : '') + (o.c || o.l) : ''; });
    const hit = T.filter(t => match(t)), n = hit.length;
    swap(ct, A.length ? `${n} of ${T.length} issues` : `${T.length} issues`); clr.hidden = !A.length;
    // the four most recently updated, and how many more
    const old = new Set($$('.flm-r', list).map(x => x.dataset.t));
    list.innerHTML = n ? hit.slice(0, 4).map(t => `<div class="flm-r" data-t="${t.t}"><span class="dot" data-s="${t.s}" aria-label="${ST[t.s]}" role="img"></span><span class="t">${t.t}</span><span class="av" data-o="${t.o}" aria-label="${OWN[t.o]}" role="img">${t.o}</span><span class="a">${age(t.a)}</span></div>`).join('') + (n > 4 ? `<div class="flm-more">and ${n - 4} more</div>` : '')
      : '<div class="flm-e">No issues match these filters</div>';
    $$('.flm-r', list).forEach((x, i) => { if (!old.has(x.dataset.t)) enter(x, i * 50); });
  }
  function wire(ch){
    const k = ch.dataset.k;
    $('.op', ch).onclick = () => { const f = A.find(x => x.k === k); f.neg = !f.neg; paint(); };
    $('.x', ch).onclick = () => {
      const had = ch.contains(document.activeElement), next = ch.nextElementSibling || ch.previousElementSibling;
      A = A.filter(x => x.k !== k); hideTip(); paint();
      if (had) ((next && $('.x', next)) || tr).focus({ preventScroll:true });
    };
  }
  clr.onclick = () => { const had = clr === document.activeElement; A = []; paint(); if (had) tr.focus({ preventScroll:true }); };
  // the menu has two steps: the fields, then the values of the one picked. Each value says how many issues it would leave.
  // It opens and closes on its own rather than through the page's shared popover, so a story playing in the card beside it
  // can't close it. Closing it while the focus is inside gives the focus back to the Filter button
  let field = null;
  const items = () => $$('.mi', field ? l2 : l1), isOpen = () => pop.classList.contains('open');
  const focusItem = m => { if (!m) return; $$('.mi', pop).forEach(x => x.tabIndex = x === m ? 0 : -1); m.focus({ preventScroll:true }); };
  function show(on, focus){
    if (on && !isOpen()){ step(null); hideTip(); placePop(tr, pop); }
    pop.classList.toggle('open', on); pop.inert = !on; tr.setAttribute('aria-expanded', on);
    if (on && focus){ const all = items(); focusItem(focus === 'last' ? all[all.length - 1] : all[0]); }
    if (!on && pop.contains(document.activeElement)) tr.focus({ preventScroll:true });
  }
  function step(k){
    const had = pop.contains(document.activeElement), from = field;
    field = k; l1.hidden = !!k; l2.hidden = !k;
    if (k){
      const f = F[k], on = A.find(x => x.k === k);
      l2.setAttribute('aria-label', f.l);
      l2.innerHTML = `<button class="mi flm-bk" role="menuitem" tabindex="-1" aria-label="Back to all fields">${I('chev-l','xs')}<span>${f.l}</span></button><div class="sep" role="separator"></div>`
        + f.o.map(o => `<button class="mi" role="menuitemradio" aria-checked="${!!on && on.v === o.v}" tabindex="-1" data-v="${o.v}">${o.g || ''}<span>${o.l}</span><span class="r num">${T.filter(t => match(t, k) && f.test(t, o.v)).length}</span><span class="ck">${I('check','xs')}</span></button>`).join('');
      $('.flm-bk', l2).onclick = () => step(null);
      $$('.mi[data-v]', l2).forEach(m => m.onclick = () => {
        const v = k === 'date' ? +m.dataset.v : m.dataset.v, f = A.find(x => x.k === k);
        if (f){ f.v = v; f.neg = false; } else A.push({ k, v, neg:false });
        $$('.mi[data-v]', l2).forEach(x => x.setAttribute('aria-checked', x === m)); paint();
        // the pick shows for a moment before the menu fades
        c.later(120, () => show(false));
      });
    }
    if (had) focusItem(k ? ($('.mi[aria-checked="true"]', l2) || $$('.mi', l2)[1]) : $(`.mi[data-k="${from}"]`, l1) || fields[0]);
  }
  fields.forEach(m => m.onclick = () => step(m.dataset.k));
  // a click, Enter, Space or the down arrow opens it with the focus on the first field, the up arrow on the last.
  // A story's tap opens it without moving the focus
  c.on(tr, 'click', e => show(!isOpen(), e.isTrusted && 'first'));
  c.on(tr, 'keydown', e => { if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); show(true, e.key === 'ArrowUp' ? 'last' : 'first'); } });
  c.on(document, 'pointerdown', e => { if (isOpen() && !pop.contains(e.target) && !tr.contains(e.target)) show(false); });
  c.on(window, 'resize', () => show(false));
  // inside the menu: the arrow keys move and wrap, Home and End jump to the ends, the right arrow opens a field's values
  // and the left arrow goes back, Escape closes it and Tab leaves it
  c.on(pop, 'keydown', e => {
    const all = items(), i = all.indexOf(document.activeElement);
    const go = { ArrowDown:all[(i + 1) % all.length], ArrowUp:all[(i - 1 + all.length) % all.length], Home:all[0], End:all[all.length - 1] }[e.key];
    if (go){ e.preventDefault(); focusItem(go); }
    else if (e.key === 'ArrowRight' && !field && all[i]){ e.preventDefault(); step(all[i].dataset.k); }
    else if (e.key === 'ArrowLeft' && field){ e.preventDefault(); step(null); }
    else if (e.key === 'Escape'){ e.preventDefault(); e.stopPropagation(); show(false); }
    else if (e.key === 'Tab') setTimeout(() => show(false));
  });
  show(false); paint();
  // the preview's story: filter to open issues, then to Maya's, and watch the count drop; then take the status filter off
  c.story(async s => {
    await s.beat(3); await s.tap(tr); await s.beat(2);
    await s.tap($('.mi[data-k="status"]', l1)); await s.beat(2);
    await s.tap($('.mi[data-v="open"]', l2)); s.away(); await s.beat(4);
    await s.tap(tr); await s.beat(2);
    await s.tap($('.mi[data-k="owner"]', l1)); await s.beat(2);
    await s.tap($('.mi[data-v="MK"]', l2)); s.away(); await s.beat(4);
    await s.tap($('.flm-ch[data-k="status"] .x', chips)); s.away(); await s.beat(4);
  });
});

c129.css:
/* ---------- Browser session ---------- */
/* the agent browsing for you: a small browser frame with the page it is on drawn as a wireframe, the steps under it, and
   Pause and Take over. When the page gets in its way it stops and asks, and with Take over the page is yours to use */
.bws{width:100%;max-width:440px;margin:0 auto;padding:6px}
.bws-h{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 10px 10px}
.bws-ht{display:flex;flex-direction:column;min-width:0}
.bws-ht b{font-weight:500;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-st{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-ctl{display:flex;align-items:center;gap:4px;flex:none}
.bws-take[aria-pressed="true"]{background:var(--accent-bg);color:var(--accent-fg,var(--accent));box-shadow:none}
.bws-win{margin:0 4px;border-radius:var(--r-in);border:1px solid var(--line);overflow:hidden;transition:border-color .3s}
.bws.you .bws-win{border-color:var(--accent-mark,var(--accent))}
.bws-bar{display:flex;align-items:center;gap:8px;height:36px;padding:0 8px 0 10px;background:var(--wash);border-bottom:1px solid var(--line)}
.bws-dots{display:flex;gap:4px;flex:none}
.bws-dots i{width:7px;height:7px;border-radius:50%;background:var(--faint)}
.bws-url{flex:1;min-width:0;display:flex;align-items:center;gap:6px;height:24px;padding:0 10px;border-radius:var(--r-pill);background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);font-size:12px;color:var(--fg2)}
.bws-url .i{color:var(--muted)}
.bws-url span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-vp{position:relative;height:156px;overflow:hidden;background:var(--surface)}
/* the page itself, drawn small: real words where they matter, grey lines for the rest */
.bws-pg{position:absolute;left:0;right:0;top:0;padding:12px 14px;display:flex;flex-direction:column;gap:10px;font-size:12px;color:var(--fg2);transition:transform .8s var(--ease)}
.bws-ln{display:block;height:6px;border-radius:3px;background:var(--chip)}
.bws-nav{display:flex;align-items:center;gap:12px;font-size:11.5px;color:var(--muted);white-space:nowrap}
.bws-nav b{display:flex;align-items:center;gap:6px;margin-right:auto;font-weight:500;color:var(--fg)}
.bws-nav b::before{content:"";width:12px;height:12px;border-radius:4px;background:var(--fg)}
.bws-nav .on{color:var(--fg)}
.bws-hd{font-size:13px;font-weight:500;color:var(--fg)}
.bws-q{display:flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:var(--r-pill);box-shadow:inset 0 0 0 1px var(--line);color:var(--fg);white-space:nowrap;overflow:hidden}
.bws-res{display:flex;flex-direction:column;gap:2px;min-width:0}
.bws-res b{font-weight:500;color:var(--pb);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;align-self:flex-start;max-width:100%}
.bws-res span{font-size:11.5px;color:var(--muted)}
.bws-cta{align-self:flex-start;height:22px;padding:0 10px;display:inline-flex;align-items:center;border-radius:var(--r-pill);background:var(--chip);font-size:11.5px;color:var(--fg2)}
.bws-tb{display:flex;flex-direction:column;border-radius:8px;box-shadow:inset 0 0 0 1px var(--line)}
.bws-tb div{display:flex;justify-content:space-between;gap:12px;padding:5px 10px;border-top:1px solid var(--line)}
.bws-tb div:first-child{border-top:0;font-size:11.5px;color:var(--muted)}
.bws-tb .num{padding:0 4px;margin:0 -4px;border-radius:4px;color:var(--fg);transition:background .3s,color .3s}
/* a price the agent has taken is marked like a highlighter, in the accent fill */
.bws-tb .num.hit{background:var(--accent);color:var(--on-accent)}
/* what the agent is about to press gets a ring, and its own pointer glides there */
.bws-vp .aim{outline:1.5px solid var(--accent-mark,var(--accent));outline-offset:2px;border-radius:4px}
.bws-cur{position:absolute;left:0;top:0;width:14px;height:14px;z-index:2;color:var(--accent-mark,var(--accent));pointer-events:none;opacity:0;transition:transform .7s var(--ease),opacity .2s}
.bws-cur.on{opacity:1}
.bws-cur svg{display:block;width:14px;height:14px;transition:transform .16s var(--ease)}
.bws-cur svg path{fill:currentColor;stroke:var(--surface);stroke-width:1.4;stroke-linejoin:round}
.bws-cur.down svg{transform:scale(.8)}
/* the page's own cookie banner, the thing in the agent's way */
.bws-ck{position:absolute;left:8px;right:8px;bottom:8px;z-index:1;display:flex;align-items:center;gap:6px;padding:6px 6px 6px 10px;border-radius:10px;background:var(--raised);box-shadow:var(--shadow-pop);font-size:12px;color:var(--fg);transform:translateY(calc(100% + 12px));transition:transform .5s var(--ease)}
.bws-ck.on{transform:none}
.bws-ck span{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-ck button{flex:none;height:24px;padding:0 9px;border-radius:var(--r-pill);font-size:11.5px;background:var(--chip);color:var(--fg)}
.bws-ck button+button{background:var(--ink);color:var(--on-ink)}
.bws:not(.you) .bws-ck button{cursor:default}
.bws-steps{list-style:none;margin:0;padding:8px 0 0;display:flex;flex-direction:column}
.bws-s{display:flex;align-items:flex-start;gap:10px;padding:6px 10px;font-size:13px;color:var(--muted)}
.bws-s .g{width:16px;height:19.5px;display:grid;place-items:center;flex:none;color:var(--faint)}
.bws-s .g .spin{width:11px;height:11px;color:var(--accent-fg,var(--accent))}
.bws-s.done{color:var(--fg2)}.bws-s.done .g{color:var(--ok)}
.bws-s.run,.bws-s.wait{color:var(--fg)}
.bws-s.wait .g{color:var(--warn)}
.bws.paused .bws-s .g .spin{animation-play-state:paused;color:var(--muted)}
.bws-t{flex:1;min-width:0;display:flex;flex-direction:column}
.bws-t>span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bws-t .d{font-size:12px;color:var(--muted)}
.bws-s.wait .d{color:var(--warn)}
.bws-ask{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:8px}
.bws-sum{display:flex;align-items:center;gap:8px;margin:8px 4px 2px;padding:10px 12px;border-radius:12px;background:var(--ok-bg);font-size:13px}
.bws-sum svg{color:var(--ok);flex:none}
.bws-sum span{min-width:0}

